import java.io.*;
import java.text.DecimalFormat;
import java.util.*;

// Independent reference: Prim with restarts (= minimum spanning FOREST, matching what
// Kruskal-without-a-connectivity-check produces) + explicit invariant checks.
public class Prim {
    public static void main(String[] a) throws Exception {
        Scanner in = new Scanner(new File(a[0]));
        int T = in.nextInt();
        DecimalFormat df = new DecimalFormat("0.0");
        StringBuilder out = new StringBuilder();
        int caseNo = 0;
        while (T != 0) {
            T--; caseNo++;
            int C = in.nextInt();
            int[] xs = new int[C], ys = new int[C];
            for (int i = 0; i < C; i++) { xs[i] = in.nextInt(); ys[i] = in.nextInt(); }
            double[][] L = new double[C][C];
            boolean[] usable = new boolean[C];
            for (int i = 0; i < C; i++)
                for (int j = 0; j < C; j++) {
                    if (i == j) { L[i][j] = Double.MAX_VALUE; continue; }
                    double d = Math.sqrt(Math.pow(xs[i]-xs[j],2)+Math.pow(ys[i]-ys[j],2));
                    L[i][j] = (d >= 10.0 && d <= 1000.0) ? d : Double.MAX_VALUE;
                    if (L[i][j] != Double.MAX_VALUE) { usable[i]=true; usable[j]=true; }
                }
            boolean allUsable = true;
            for (int i = 0; i < C; i++) if (!usable[i]) allUsable = false;
            if (!allUsable) { out.append("oh!\n");
                System.err.println("  [case "+caseNo+" C="+C+"] isolated vertex -> oh!"); continue; }

            boolean[] done = new boolean[C];
            double sum = 0.0; List<int[]> tree = new ArrayList<>(); int comps = 0;
            for (int start = 0; start < C; start++) {
                if (done[start]) continue;
                comps++;
                double[] key = new double[C]; int[] par = new int[C];
                Arrays.fill(key, Double.MAX_VALUE); Arrays.fill(par, -1);
                key[start] = 0.0;
                Set<Integer> comp = new HashSet<>();
                while (true) {
                    int u = -1; double best = Double.MAX_VALUE;
                    for (int v = 0; v < C; v++) if (!done[v] && key[v] < best) { best = key[v]; u = v; }
                    if (u == -1) break;
                    done[u] = true; comp.add(u);
                    if (par[u] != -1) { sum += key[u]; tree.add(new int[]{par[u], u}); }
                    for (int v = 0; v < C; v++)
                        if (!done[v] && L[u][v] != Double.MAX_VALUE && L[u][v] < key[v]) { key[v]=L[u][v]; par[v]=u; }
                }
            }
            // INVARIANTS: forest has V - (#components) edges; acyclic by construction; check union-find too
            int[] dsu = new int[C]; Arrays.fill(dsu, -1);
            int cyc = 0;
            for (int[] e : tree) {
                int r1 = e[0], r2 = e[1];
                while (dsu[r1] > -1) r1 = dsu[r1];
                while (dsu[r2] > -1) r2 = dsu[r2];
                if (r1 == r2) cyc++; else dsu[r1] = r2;
            }
            System.err.println("  [case "+caseNo+" C="+C+"] comps="+comps
                + " edges="+tree.size()+" expected(V-comps)="+(C-comps)
                + " cyclesDetected="+cyc
                + " spanning="+(comps==1)+" (V-1="+(C-1)+" edges? "+(tree.size()==C-1)+")"
                + " primWeight*100="+df.format(sum*100.0));
            out.append(df.format(sum * 100.0)).append("\n");
        }
        System.out.print(out);
    }
}
